// ─────────────────────────────────────────────────────────────────────────
//  01 · epoch roundtrip                                        ★☆☆ warm-up
//  concepts: Unix time · instants vs offsets
// ─────────────────────────────────────────────────────────────────────────
//
//  JWT exp claims, Redis TTLs and most wire formats speak Unix seconds.
//  An instant has ONE Unix number, whatever offset it is written with.

using static Bootcamp.Check;

long ToUnixSeconds(DateTimeOffset t)
{
    return t.ToUnixTimeSeconds();
}

DateTimeOffset FromUnix(long value)
{
    return Math.Abs(value) >= 100_000_000_000
        ? DateTimeOffset.FromUnixTimeMilliseconds(value)
        : DateTimeOffset.FromUnixTimeSeconds(value);
}

