//  05 · booking overlap                                        ★★☆ core
//  concepts: half-open ranges · overlap test
// ─────────────────────────────────────────────────────────────────────────
//
//  Hotel rule: the checkout day is free for the next guest. Stays are
//  half-open [checkIn, checkOut) — back-to-back bookings never conflict.

using static Bootcamp.Check;

bool Overlaps(DateOnly aStart, DateOnly aEnd, DateOnly bStart, DateOnly bEnd)
{
    return aStart < bEnd && bStart < aEnd;
}

int OccupiedNights(List<(DateOnly In, DateOnly Out)> stays)
{
    int nights = 0;
    DateOnly? coveredUntil = null;   // the furthest checkout seen so far
    foreach (var (inDay, outDay) in stays.OrderBy(s => s.In))
    {
        var start = coveredUntil is DateOnly c && c > inDay ? c : inDay;
        if (outDay > start) nights += outDay.DayNumber - start.DayNumber;
        if (coveredUntil is null || outDay > coveredUntil) coveredUntil = outDay;
    }
    return nights;
}

// ──────────────────────────── tests ──────────────────────────────────────

Test("back-to-back stays do not overlap (boundary: checkout meets check-in)", () =>
    Eq(Overlaps(new DateOnly(2026, 7, 10), new DateOnly(2026, 7, 13), new DateOnly(2026, 7, 13), new DateOnly(2026, 7, 15)), false));

Test("a contained stay overlaps", () =>
    Eq(Overlaps(new DateOnly(2026, 7, 10), new DateOnly(2026, 7, 20), new DateOnly(2026, 7, 12), new DateOnly(2026, 7, 14)), true));

Test("identical stays overlap", () =>
    Eq(Overlaps(new DateOnly(2026, 7, 10), new DateOnly(2026, 7, 13), new DateOnly(2026, 7, 10), new DateOnly(2026, 7, 13)), true));

Test("disjoint stays do not overlap", () =>
    Eq(Overlaps(new DateOnly(2026, 7, 1), new DateOnly(2026, 7, 5), new DateOnly(2026, 7, 10), new DateOnly(2026, 7, 12)), false));

DateOnly July(int day) => new DateOnly(2026, 7, day);

Test("OccupiedNights of one stay Jul 10 -> Jul 13 is 3", () =>
    Eq(OccupiedNights([(July(10), July(13))]), 3));

Test("OccupiedNights of no stays is 0 (boundary)", () =>
    Eq(OccupiedNights([]), 0));

Test("a night covered by two stays counts once", () =>
{
    Eq(OccupiedNights([(July(10), July(13)), (July(12), July(15))]), 5);
    Eq(OccupiedNights([(July(1), July(10)), (July(3), July(4))]), 9);
});

Test("unsorted, back-to-back and separate stays add up", () =>
    Eq(OccupiedNights([(July(20), July(22)), (July(10), July(13)), (July(13), July(15))]), 7));

