// ─────────────────────────────────────────────────────────────────────────
//  09 · dst wall clock                                         ★★★ stretch
//  concepts: TimeZoneInfo · DST gap and overlap · calendar vs elapsed
// ─────────────────────────────────────────────────────────────────────────
//
//  "Same time tomorrow" and "24 hours later" are different instants twice a
//  year. Wall-clock times inside the spring gap never happen; times inside
//  the autumn overlap happen twice. The zone is always named explicitly.

using System.Globalization;
using static Bootcamp.Check;

var NewYork = TimeZoneInfo.FindSystemTimeZoneById("America/New_York");

string PlusOneDay(DateTime local)
{
    return local.AddDays(1).ToString("yyyy-MM-dd'T'HH:mm", CultureInfo.InvariantCulture);
}

string PlusTwentyFourHours(DateTime local)
{
    var utc = TimeZoneInfo.ConvertTimeToUtc(local, NewYork).AddHours(24);
    return TimeZoneInfo.ConvertTimeFromUtc(utc, NewYork).ToString("yyyy-MM-dd'T'HH:mm", CultureInfo.InvariantCulture);
}

string RunAt(DateOnly date, TimeOnly wall)
{
    var local = date.ToDateTime(wall, DateTimeKind.Unspecified);
    if (NewYork.IsInvalidTime(local))
    {
        // the gap is the offset change across the transition (one hour in New York)
        var gap = NewYork.GetUtcOffset(local.AddDays(1)) - NewYork.GetUtcOffset(local.AddDays(-1));
        local = local.Add(gap);
    }
    var offset = NewYork.IsAmbiguousTime(local)
        ? NewYork.GetAmbiguousTimeOffsets(local).Max()   // the earlier occurrence has the larger offset
        : NewYork.GetUtcOffset(local);
    return new DateTimeOffset(local, offset).ToString("yyyy-MM-dd'T'HH:mmzzz", CultureInfo.InvariantCulture);
}

// ──────────────────────────── tests ──────────────────────────────────────

Test("fall back: plus one day keeps 09:00", () =>
    Eq(PlusOneDay(new DateTime(2025, 11, 1, 9, 0, 0)), "2025-11-02T09:00"));

Test("fall back: plus 24 hours lands at 08:00 (boundary: that Sunday has 25 hours)", () =>
    Eq(PlusTwentyFourHours(new DateTime(2025, 11, 1, 9, 0, 0)), "2025-11-02T08:00"));

Test("spring forward: plus one day keeps 09:00", () =>
