Test("spring forward: plus 24 hours lands at 10:00 (that Sunday has 23 hours)", () =>
    Eq(PlusTwentyFourHours(new DateTime(2025, 3, 8, 9, 0, 0)), "2025-03-09T10:00"));

Test("02:30 on 2025-03-09 never happens: the job runs at 03:30 EDT (boundary: the gap)", () =>
    Eq(RunAt(new DateOnly(2025, 3, 9), new TimeOnly(2, 30)), "2025-03-09T03:30-04:00"));

Test("01:30 on 2025-11-02 happens twice: the job runs at the first one, EDT (boundary: the overlap)", () =>
    Eq(RunAt(new DateOnly(2025, 11, 2), new TimeOnly(1, 30)), "2025-11-02T01:30-04:00"));

Test("an ordinary summer and winter 02:30 keep their own offsets", () =>
{
    Eq(RunAt(new DateOnly(2025, 7, 1), new TimeOnly(2, 30)), "2025-07-01T02:30-04:00");
    Eq(RunAt(new DateOnly(2025, 1, 15), new TimeOnly(2, 30)), "2025-01-15T02:30-05:00");
